class Contract {
  readonly customer: string;
  readonly supplier: string;
  private constructor(p: ContractProps) { this.customer = p.customer; this.supplier = p.supplier; }
  static isValid(p: Partial<ContractProps>): p is ContractProps {
    return typeof p.customer === 'string' && p.customer.length > 0
        && typeof p.supplier === 'string' && p.supplier.length > 0; }
  static create(p: Partial<ContractProps>): Contract | MissingProps {
    return Contract.isValid(p) ? new Contract(p) : new MissingProps(['customer', 'supplier']); }
}
const contract = Contract.create({ customer: 'acme', supplier: 'globex' });   // no `new` outside
